additionalExercises.referenceSolution:
#include <deque>
#include <iostream>
#include <print>
#include <sstream>
#include <stdexcept>
#include <string>
#include <vector>

struct Component {
    std::string name;
    explicit Component(const std::string &n) : name(n) {
        if (n.starts_with('!')) {
            throw std::runtime_error("сбой " + n);
        }
        std::println("+{}", name);
    }
    ~Component() {
        std::println("-{}", name);
    }
};

class Assembly {
public:
    explicit Assembly(const std::vector<std::string> &names) {
        try {
            for (const std::string &n : names) {
                parts_.emplace_back(n);
            }
        } catch (...) {
            dismantle();
            throw;
        }
        std::println("собрано {}", parts_.size());
    }

    ~Assembly() {
        dismantle();
    }

private:
    void dismantle() {
        while (!parts_.empty()) {
            parts_.pop_back();
        }
    }

    std::deque<Component> parts_;
};

int main() {
    std::string line;
    while (std::getline(std::cin, line)) {
        std::istringstream in(line);
        std::vector<std::string> names;
        std::string name;
        while (in >> name) {
            names.push_back(name);
        }
        try {
            const Assembly assembly(names);
        } catch (const std::exception &e) {
            std::println("ошибка: {}", e.what());
        }
    }
    return 0;
}

